import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading ensures availability before frame 0
const { fontFamily: interFamily } = loadInter();



export type HookTextProps = Record<string, any>;

const NdisHook: React.FC<HookTextProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
  line1Text = "I HAVE AUDITED",
  line2Suffix = "OF NDIS",
  line3Text = "SERVICE PROVIDERS",
  counterStart = 100,
  counterEnd = 300,
  counterDurationFrames = 60,
  highlightColor = "#D2FF03",
  textColor = "#FFFFFF",
  shadowColor = "rgba(0, 0, 0, 0.65)",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background cleanly
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Responsive sizing based on canvas width
  const baseFontSize = width * 0.065;
  const layoutPadding = width * 0.08;

  // Layered soft shadow for a professional, clean depth effect
  const shadowBase = width * 0.002;
  const textShadow = `0px ${shadowBase * 2}px ${
    shadowBase * 4
  }px ${shadowColor}, 0px ${shadowBase}px ${shadowBase * 2}px ${shadowColor}`;

  // Staggered entry animations
  const line1Enter = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 150 },
  });
  const line2Enter = spring({
    frame: frame - 12,
    fps,
    config: { damping: 14, stiffness: 150 },
  });
  const line3Enter = spring({
    frame: frame - 24,
    fps,
    config: { damping: 14, stiffness: 150 },
  });

  // Counter logic calculating directly from the frame without mutable state
  const rawCounter = interpolate(
    frame,
    [12, 12 + counterDurationFrames], // Starts as line 2 begins animating in
    [counterStart, counterEnd],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Single digit increment effect via Math.floor
  const currentCounter = Math.floor(rawCounter);

  const sharedTextStyle: React.CSSProperties = {
    fontFamily: interFamily,
    fontSize: `${baseFontSize}px`,
    fontWeight: 900, // Black/Extra Bold for strong hook
    textShadow,
    lineHeight: 1.05,
    transition: "none",
    textTransform: "uppercase",
    margin: 0,
    letterSpacing: "-0.02em",
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "flex-start",
        paddingLeft: layoutPadding,
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          maxWidth: "85%", // Keeps text contained naturally
        }}
      >
        {/* Line 1: Standard Text */}
        <div style={{ overflow: "hidden", paddingBottom: "10px" }}>
          <div
            style={{
              ...sharedTextStyle,
              color: textColor,
              transform: `translateY(${interpolate(
                line1Enter,
                [0, 1],
                [100, 0]
              )}%)`,
              opacity: line1Enter,
            }}
          >
            {line1Text}
          </div>
        </div>

        {/* Line 2: Hook Counter + Suffix */}
        <div style={{ overflow: "hidden", paddingBottom: "10px" }}>
          <div
            style={{
              ...sharedTextStyle,
              color: highlightColor,
              transform: `translateY(${interpolate(
                line2Enter,
                [0, 1],
                [100, 0]
              )}%)`,
              opacity: line2Enter,
              display: "flex",
              flexDirection: "row",
              alignItems: "center",
            }}
          >
            {/* Tabular nums prevent horizontal jitter when digits change */}
            <span style={{ fontVariantNumeric: "tabular-nums" }}>
              {currentCounter}
            </span>
            <span style={{ whiteSpace: "pre" }}>{" "}{line2Suffix.trimStart()}</span>
          </div>
        </div>

        {/* Line 3: Highlight Continuation */}
        <div style={{ overflow: "hidden", paddingBottom: "10px" }}>
          <div
            style={{
              ...sharedTextStyle,
              color: highlightColor,
              transform: `translateY(${interpolate(
                line3Enter,
                [0, 1],
                [100, 0]
              )}%)`,
              opacity: line3Enter,
            }}
          >
            {line3Text}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default NdisHook;